<?php
$pageTitle = 'Progress updates';
$taskId=(int)($_GET['task_id']??$_POST['task_id']??0);
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    $taskId=(int)($_POST['task_id']??0); $percent=filter_var($_POST['progress_percentage']??null,FILTER_VALIDATE_INT); $status=(string)($_POST['status']??'in_progress'); $notes=trim((string)($_POST['notes']??''));
    if (!task_visible($pdo,$taskId)) { flash('error','You do not have access to update that task.'); redirect('index.php?page=progress'); }
    if ($percent===false || $percent<0 || $percent>100) { flash('error','Progress must be a number between 0 and 100.'); redirect('index.php?page=progress&task_id='.$taskId); }
    if (!in_array($status,['pending','in_progress','blocked','completed'],true)) $status='in_progress';
    if ($status==='completed') $percent=100;
    if ($percent===100 && $status!=='blocked') $status='completed';
    $st=$pdo->prepare('UPDATE tasks SET progress_percent=?,status=? WHERE id=?'); $st->execute([$percent,$status,$taskId]);
    $st=$pdo->prepare('INSERT INTO progress_updates (task_id,user_id,progress_percentage,status,notes) VALUES (?,?,?,?,?)'); $st->execute([$taskId,(int)user()['id'],$percent,$status,$notes?:null]);
    flash('success','Progress update saved.'); redirect('index.php?page=progress&task_id='.$taskId);
}
[$scope,$scopeParams]=current_task_access_sql();
$sql="SELECT t.id,t.title,t.project_id,t.status,t.progress_percent,t.due_date,p.name AS project_name,u.full_name AS assignee_name FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to WHERE 1=1 $scope ORDER BY t.due_date IS NULL,t.due_date";
$st=$pdo->prepare($sql); $st->execute($scopeParams); $tasks=$st->fetchAll();
$selected=null; foreach($tasks as $t){ if((int)$t['id']===$taskId) {$selected=$t;break;} } if(!$selected && $tasks && $taskId===0) $selected=$tasks[0];
$history=[]; if($selected){$st=$pdo->prepare('SELECT pu.*,u.full_name FROM progress_updates pu JOIN users u ON u.id=pu.user_id WHERE pu.task_id=? ORDER BY pu.created_at DESC LIMIT 30');$st->execute([(int)$selected['id']]);$history=$st->fetchAll();}
require __DIR__ . '/../inc/header.php';
?>
<div class="page-toolbar"><p class="muted">Record site updates and keep the task schedule aligned with actual progress.</p></div>
<div class="content-grid progress-grid"><section class="panel"><div class="panel-heading"><div><h3>Record progress</h3><p>Select a task and provide the latest status.</p></div></div>
<?php if(!$tasks): ?><div class="empty-state"><div class="empty-icon">↗</div><h3>No available tasks</h3><p>Tasks assigned to you will appear here.</p></div><?php else: ?><form method="post" class="stack-form"><?= csrf_field() ?><label>Task<select name="task_id" required onchange="this.form.querySelector('[name=task_preview]').value=this.options[this.selectedIndex].dataset.info||'';"><?php foreach($tasks as $t): ?><option value="<?= (int)$t['id'] ?>" data-info="<?= e($t['project_name'].' · Current progress '.$t['progress_percent'].'%') ?>" <?= (int)$selected['id']===(int)$t['id']?'selected':'' ?>><?= e($t['title'].' — '.$t['project_name']) ?></option><?php endforeach; ?></select></label><input type="text" name="task_preview" readonly class="readonly-input" value="<?= e($selected['project_name'].' · Current progress '.$selected['progress_percent'].'%') ?>"><div class="progress-edit"><div><span>Current recorded progress</span><strong><?= (int)$selected['progress_percent'] ?>%</strong></div><div class="progress-line progress-large"><span style="width:<?= (int)$selected['progress_percent'] ?>%"></span></div></div><label>Updated progress (%)<input type="number" name="progress_percentage" min="0" max="100" step="1" value="<?= (int)$selected['progress_percent'] ?>" required></label><label>Task status<select name="status"><?php foreach(['pending','in_progress','blocked','completed'] as $s): ?><option value="<?= e($s) ?>" <?= $selected['status']===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach; ?></select></label><label>Site notes / work completed<textarea name="notes" rows="4" maxlength="3000" placeholder="Describe what was completed, issues encountered, or what remains."></textarea></label><button class="btn btn-primary" type="submit">Save progress update</button><p class="muted small">A permanent history entry is saved each time you submit this form.</p></form><?php endif; ?></section>
<section class="panel"><div class="panel-heading"><div><h3>Update history</h3><p><?= $selected?e($selected['title']):'Select a task to review updates' ?></p></div></div><?php if(!$selected): ?><div class="empty-inline">No task selected.</div><?php elseif(!$history): ?><div class="empty-state compact"><div class="empty-icon">◷</div><h3>No history yet</h3><p>The first update will appear here.</p></div><?php else: ?><div class="timeline"><?php foreach($history as $h): ?><article class="timeline-item"><span class="timeline-dot"></span><div class="timeline-head"><strong><?= e($h['full_name']) ?></strong><span><?= e(date('d M Y, H:i',strtotime($h['created_at']))) ?></span></div><div class="timeline-meta"><span class="status status-<?= e($h['status']) ?>"><?= e(status_label($h['status'])) ?></span><strong><?= (int)$h['progress_percentage'] ?>%</strong></div><div class="progress-line"><span style="width:<?= (int)$h['progress_percentage'] ?>%"></span></div><?php if($h['notes']): ?><p><?= nl2br(e($h['notes'])) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section></div>
<?php require __DIR__ . '/../inc/footer.php'; ?>
